def build_recall_line(paper_brief, task_brief, work_brief):
    def n(f):
        try:
            return len(f())
        except Exception:
            return 0
    return f'召回：论文 {n(paper_brief)} / 任务 {n(task_brief)} / 工作 {n(work_brief)}'

line = build_recall_line(lambda: [1,2,3,4], lambda: [1,2,3], lambda: [1,2,3,4,5])
assert line == '召回：论文 4 / 任务 3 / 工作 5'
line2 = build_recall_line(lambda: (_ for _ in ()).throw(RuntimeError()), lambda: [], lambda: [1])
assert '论文 0' in line2 and '任务 0' in line2 and '工作 1' in line2
print('ok', line, '|', line2)
